 CommonState seed;seed.next_instance_id=1;WalletView wallet;wallet.id="funds";wallet.balance=71;seed.wallets.insert(wallet.id,wallet);CommonStore c(seed,std::make_shared<CommonCatalog>());MilitaryCatalog cat;cat.recovery_policy=MilitaryRecoveryPolicy{};cat.supply_attrition_policy=MilitarySupplyAttritionPolicy{};GarrisonDefinition camp;camp.id="camp";camp.organization_id="org";camp.food_item_id="grain";camp.ration_per_person=1;MilitaryUnitDefinition def;def.id="unit";def.initial_soldiers=51;camp.units={def};cat.garrisons={camp};MilitaryState m;MilitaryUnitRecord unit;unit.id="unit";unit.garrison_id=unit.source_garrison_id="camp";unit.organization_id="org";for(Integer n=1;n<=51;++n)unit.member_ids.push_back("soldier:unit:"+std::to_string(n));unit.fit=unit.member_ids;m.military_units={unit};const auto members=unit.member_ids;
 auto step=[&](Integer shortage){MilitarySupplyFact food;food.id=take(c.next_id("military"));food.tick=c.tick()+1;food.organization_id="org";food.garrison_id="camp";food.item_id="grain";food.mouth_ids=m.military_units[0].fit;food.required=Integer(food.mouth_ids.size());food.shortage=shortage?food.required:0;food.consumed=food.required-food.shortage;good(c.append_fact({food.id,"military_supply","military"}));m.supply_facts.push_back(food);if(food.shortage>0&&!m.military_units[0].fit.empty())m.military_units[0].morale=std::max<Integer>(1,m.military_units[0].morale-8);DynamicStepInput phase{c.tick(),c.tick()+1,{},{},{}};MilitaryAccess a;a.rosters_before=[&](const auto& ids,Integer tick,const StableId& id){return military_rosters_before(c,m,cat,ids,tick,id,phase);};auto ids=take(step_military_supply_attrition(c,m,cat,a,phase));good(validate_military_supply_attrition_history(c,m,cat,a,&phase));if(!ids.empty()){check(!validate_military_supply_attrition_history(c,m,cat,a).ok,"stable cold cannot admit future attrition");check(!step_military_supply_attrition(c,m,cat,a,phase).ok,"actual halfday cannot be applied twice");}++c.state().identity.tick;MilitaryAccess cold;cold.rosters_before=[&](const auto& ids,Integer tick,const StableId& id){return military_rosters_before(c,m,cat,ids,tick,id);};good(validate_military_supply_attrition_history(c,m,cat,cold));auto rebuilt=take(military_rosters_current(c,m,cat,{"unit"}));check(rebuilt[0].fit==m.military_units[0].fit&&rebuilt[0].deserted==m.military_units[0].deserted&&rebuilt[0].morale==m.military_units[0].morale,"source reconstructs exact fit deserted and morale");check(m.military_units[0].member_ids==members&&m.military_units[0].fit.size()+m.military_units[0].deserted.size()==51&&c.wallet("funds")->balance==71,"all tokens and money conserved");return ids;};
 check(step(1).size()==1&&m.military_units[0].fit.size()==51&&m.military_units[0].morale==60,"first shortage records zero attrition and morale10");check(step(1).size()==1&&m.military_units[0].fit.size()==49&&m.military_units[0].morale==50,"second shortage loses ceil51x2percent");check(step(0).empty()&&m.military_units[0].fit.size()==49,"real full meal breaks shortage streak");check(step(1).size()==1&&m.military_units[0].fit.size()==49,"first shortage after meal does not catch up");check(step(1).size()==1&&m.military_units[0].fit.size()==48,"later quota uses actual eligible49 not original51");
 MilitaryAccess cold;cold.rosters_before=[&](const auto& ids,Integer tick,const StableId& id){return military_rosters_before(c,m,cat,ids,tick,id);};auto saved=m;auto common=c;m.supply_attrition.facts.erase(m.supply_attrition.facts.begin());c.state().facts.erase(saved.supply_attrition.facts.front().id);check(!validate_military_supply_attrition_history(c,m,cat,cold).ok,"deleting zero-loss source and header cannot erase shortage effect");m=saved;c=common;m.supply_attrition.facts.back().deserted_ids.push_back(m.military_units.front().fit.back());check(!validate_military_supply_attrition_history(c,m,cat,cold).ok,"inflated loss quota rejected");m=saved;m.supply_attrition.facts.back().supply_fact_id=m.supply_facts.front().id;check(!validate_military_supply_attrition_history(c,m,cat,cold).ok,"old supply cannot fund another period");m=saved;
 auto json=military_supply_attrition_codec::encode(m.supply_attrition);auto restored=take(military_supply_attrition_codec::decode(json));check(restored.facts.size()==4,"JSON keeps zero and actual loss periods");auto bad=json;bad.as<BoundaryValue::Dict>()->push_back(bad.as<BoundaryValue::Dict>()->front());check(!military_supply_attrition_codec::decode(bad).ok,"duplicate root rejected");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);writer.schema_features=military_recovery_checkpoint_feature|military_supply_attrition_checkpoint_feature;good(military_supply_attrition_codec::visit(writer,restored));good(writer.finish());MilitarySupplyAttritionState decoded;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));reader.schema_features=writer.schema_features;good(military_supply_attrition_codec::visit(reader,decoded));good(reader.finish());check(decoded.facts.back().deserted_ids==restored.facts.back().deserted_ids,"typed tail roundtrip exact tokens");CodecVisitor old(bytes);old.schema_features=military_recovery_checkpoint_feature;check(!military_supply_attrition_codec::visit(old,decoded).ok,"Military8 cannot silently serialize Military9");
 // 原命令接受后才出现的实际末员逃散：只取消不能再执行的原意图，原AI及源frame不改。
 {MilitaryState losses;MilitaryBattleRecord before;before.id="battle:1";before.rng_state="123";BattleUnit left;left.unit_id="left";left.army_id="army:left";left.fit=left.member_ids={"anonymous:left"};left.morale=50;BattleUnit right;right.unit_id="right";right.army_id="army:right";right.fit=right.member_ids={"anonymous:right"};right.morale=70;before.units={left,right};before.pending_orders={{left.unit_id,{"attack",left.position,0,right.unit_id,{},{}}}};before.ai_plans={{right.unit_id,{"attack",right.position,0,left.unit_id,{},{}}}};
  MilitarySupplyFact first;first.id="military:2";first.army_id=left.army_id;first.tick=8;first.shortage=1;MilitarySupplyFact second;second.id="military:3";second.army_id=right.army_id;second.tick=8;losses.supply_facts={first,second};MilitarySupplyAttritionFact lost;lost.id="military_attrition:4";lost.unit_id=left.unit_id;lost.supply_fact_id=first.id;lost.tick=8;lost.fit_before=lost.eligible_fit_before=lost.deserted_ids=left.fit;losses.supply_attrition.facts={lost};auto staged=take(prepare_military_supply_attrition_battle(losses,cat,before,8));check(staged.battle.units[0].fit.empty()&&staged.battle.units[0].deserted==left.fit&&staged.battle.units[0].morale==40,"same original supply moves final token exactly and totals morale10");check(staged.battle.pending_orders.empty()&&staged.battle.ai_plans[0].second.action=="wait"&&staged.interrupted_orders.size()==2,"only impossible accepted orders are cancelled with source events");check(before.units[0].fit==left.fit&&before.pending_orders.size()==1&&before.ai_plans[0].second.action=="attack"&&staged.battle.rng_state==before.rng_state,"original frame intentions and RNG stay unchanged");MilitaryCatalog oldcat;auto old=take(prepare_military_supply_attrition_battle(losses,oldcat,before,8));check(old.interrupted_orders.empty()&&old.battle.units[0].fit==left.fit&&old.battle.ai_plans[0].second.action=="attack","old disabled policy neither applies nor normalizes orders");}
